pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 fuzzBlockOffset, bytes32 fuzzHash) public {
        // fuzzBlockOffset controls how many blocks to advance after lockInGuess.
        // The crucial difference: when offset is 0 (settle in the same block as lock),
        // the reference contract disallows it (blocks[msg.sender].block = block.number+1 > current block),
        // while the buggy one uses block.number, allowing settle in the same block.
        vm.assume(fuzzBlockOffset <= 5);

        address actor = address(0x1234);
        vm.deal(actor, 2 ether);

        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(fuzzHash);
        vm.stopPrank();

        // Advance to block.number + offset; if fuzzBlockOffset == 0 we are still in the same block.
        vm.roll(block.number + fuzzBlockOffset);

        // settle must revert if block.number <= stored block (i.e., settle in same block or earlier).
        // In reference C, stored block is block.number+1, so a same-block settle is always a revert.
        // In buggy M, stored block is block.number, so same-block settle does NOT revert.
        bool didRevert;
        vm.prank(actor);
        try c.settle() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // The general invariant: a settle called in the same block as the corresponding lockInGuess MUST revert.
        assertTrue(didRevert);
    }
}

