pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        address alice = address(0x1000);
        vm.deal(alice, 2 ether);
        // Alice locks a guess
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(hash);
        uint256 initialBalance = address(c).balance;
        // Advance at least 1 block so that correct contract settles properly
        vm.roll(block.number + 2);
        vm.prank(alice);
        c.settle();
        // After one settle, the contract balance must have decreased by exactly 2 ether if the guess was correct,
        // or 0 if incorrect. In buggy version, settling in the same block would reset block to 0 without transferring,
        // but here we test the general invariant: any settle must keep the balance consistent with the guess outcome.
        // The actual invariant: address(c).balance is initialBalance - (2 ether * (success ? 1 : 0)).
        // However, the buggy version breaks this because it allows settling without enforcing block.number > guess.block,
        // but that only matters when settle is called in the same block. With vm.roll we are past that block.
        // The correct invariant must hold across all inputs, but the bug only triggers when settle is called before block advance.
        // We must encode a property that the buggy version violates for some input.
        // The property: If settle is called after lockInGuess and after the recorded block, then the guesser's block is reset to 0,
        // and calling settle again must revert. The bug resets block to 0 as well, so that invariant holds.
        // We need a different invariant that catches the missing require.
        // The core difference: In the correct version, settle can only be called when block.number > recorded block.
        // In the buggy version, settle can be called when block.number == recorded block (immediately after lockInGuess).
        // If it is called in the same block, blockhash returns 0, so the guess is never considered correct, no ether is sent,
        // but block is reset to 0, allowing the guesser to lock a new guess and potentially get a correct guess later,
        // effectively getting a free pass to reset a bad guess without losing ether?
        // Actually, the original contract requires 1 ether to lock, and guess can be settled only if blockhash matches.
        // The invariant: After a settle call that does not transfer ether (incorrect guess), the guesser's block must be 0,
        // and they must be able to lock a new guess by paying 1 ether again.
        // The bug allows settle to be called in the same block where blockhash is 0, so it never transfers ether.
        // This means the guesser can call settle immediately after lockInGuess, resetting block to 0 without the need
        // for block.number > recorded block, effectively allowing them to retry without any wait.
        // The invariant we can test: After lockInGuess and a settle call, the block field of the guesser must be 0.
        // That holds in both versions. We need a property that fails only in the buggy version for some inputs.
        // Property: If lockInGuess is called and then settle is called in the same block, the contract balance must remain
        // unchanged (no ether transferred). This is true in both. The difference is that in the correct version,
        // settle would revert in the same block because block.number > recorded block is false. So the correct version
        // prevents calling settle in the same block entirely. The buggy version allows it.
        // Therefore, the property: "Calling settle immediately after lockInGuess in the same block must revert."
        // The correct version reverts, the buggy version does not.
        // That is the general rule: settle() must revert if block.number <= guesses[caller].block.
        // Since we cannot use assertions in setUp and must have exactly one assertion on c,
        // we can test: after lockInGuess, settle() in the same block reverts (correct) vs succeeds (bug).
        // But the fuzzer provides the hash; we need to ensure we are in the same block.
        // So we lock, then immediately try settle without rolling block. That's an invariant: settle must revert.
        address bob = address(0x2000);
        vm.deal(bob, 2 ether);
        vm.prank(bob);
        c.lockInGuess{value: 1 ether}(hash);
        // Do not advance block
        vm.prank(bob);
        (bool success,) = address(c).call(abi.encodeWithSignature("settle()"));
        // In correct version, success is false; in buggy version, success is true.
        // That's the property: settle must fail when block.number <= guess.block.
        assertTrue(!success);
    }
}

